def assign_general_project(apps, schema_editor):
    """Every instance belongs to a project: put existing ones in their owner's "General" project."""
    db = schema_editor.connection.alias
    User = apps.get_model('auth', 'User')
    Instance = apps.get_model('orchestrator', 'Instance')
    Project = apps.get_model('orchestrator', 'Project')
    fallback_owner = User.objects.using(db).filter(is_superuser=True).order_by('id').first()
    for instance in Instance.objects.using(db).filter(project__isnull=True):
        owner = instance.owner or fallback_owner
        if owner is None:
            continue
        project, _ = Project.objects.using(db).get_or_create(owner=owner, name='General')
        instance.project = project
        instance.save(using=db, update_fields=['project'])


